func loadGoldenCLI(t *testing.T) *goldenFile {
	t.Helper()
	raw, err := os.ReadFile(filepath.Join("testdata", "goldencli.golden.json"))
	if err != nil {
		t.Fatalf("read golden: %v", err)
	}
	var g goldenFile
	if err := json.Unmarshal(raw, &g); err != nil {
		t.Fatalf("parse golden: %v", err)
	}
	return &g
}

// unfold replaces the golden's folded roots with the real temp roots
// (the generator's fold, reversed).
func unfold(s, appTmp, vaultsTmp string) string {
	s = strings.ReplaceAll(s, "<app>", appTmp)
	s = strings.ReplaceAll(s, "<vaults>", vaultsTmp)
	return s
}

// fold replaces the replay's real temp roots with the golden's folded
// placeholders.
func fold(s, appTmp, vaultsTmp string) string {
	s = strings.ReplaceAll(s, appTmp, "<app>")
	s = strings.ReplaceAll(s, vaultsTmp, "<vaults>")
	return s
}

// decodeConfig turns a raw golden JSON config (with folded paths) into
// an OrderedMap over the real temp roots — through the house decoder
// (integral literals decode as int64, the T-50 law).
func decodeConfig(t *testing.T, raw json.RawMessage, appTmp, vaultsTmp string) *storage.OrderedMap {
	t.Helper()
	fixed := []byte(unfold(string(raw), appTmp, vaultsTmp))
	om, err := storage.DecodeJSON(fixed)
	if err != nil {
		t.Fatalf("decode config: %v", err)
	}
	return om
}

// replayCLI builds the shell bound to a buffer with the frozen clock
// and the golden's seam answers.
func replayCLI(t *testing.T, g *goldenFile, in string) (*CLI, *bytes.Buffer) {
	t.Helper()
	buf := &bytes.Buffer{}
	latency := g.Env.NetStub.LatencyMs
	c := &CLI{
		Out:       buf,
		ErrW:      buf,
		In:        strings.NewReader(in),
		Now:       frozenClock,
		IsATTYIn:  func() bool { return false },
		IsATTYOut: func() bool { return false },
		IsDir: func(p string) bool {
			fi, err := os.Stat(p)
			return err == nil && fi.IsDir()
		},
		ProbeInternet: func(cfg any, timeoutS float64) connectioncheck.ProbeInternetResult {
			return connectioncheck.ProbeInternetResult{
				Online:    g.Env.NetStub.Online,
				Endpoint:  g.Env.NetStub.Endpoint,
				Status:    g.Env.NetStub.Status,
				LatencyMs: latency,
				Detail:    g.Env.NetStub.Detail,
			}
		},
		AIStatus: func(cfg any, timeoutS float64) connectioncheck.AIStatusResult {
			return connectioncheck.AIStatusResult{
				State:  g.Env.AIStub.State,
				Kind:   g.Env.AIStub.Kind,
				Engine: g.Env.AIStub.Engine,
				Detail: g.Env.AIStub.Detail,
				Short:  g.Env.AIStub.Short,
			}
		},
		OllamaModels: func(baseURL string, timeoutS float64) ([]string, error) {
			return g.Env.OllamaModels, nil
		},
	}
	return c, buf
}

// buildEnv rebuilds the crafted environment from the golden's env
// record: the vault dirs, the taxonomy file, config.json +
// bad-config.json, cache.db with every row the reference's own
// methods produced (the quarantine rows pin the reference's frozen
// stamps — the replay's cache.db is fixture state, inserted directly),
// and the SESSION-028 wirings' crafted files (the battery config + the
// session file, the detect configs, the wizard configs — the scripted
// answers live in the sections themselves).
func buildEnv(t *testing.T, g *goldenFile) (appTmp, vaultsTmp string) {
	t.Helper()
	// FIXED-LENGTH roots: the reference generator's mkdtemp suffixes are
	// exactly 8 runes, and the run-config card's right-side padding bakes
	// the path lengths into the golden's bytes — the replay's roots must
	// be the same width ("goreplay" = 8) for the folded bytes to match.
	appTmp = filepath.Join(os.TempDir(), "gc-cli-app-goreplay")
	vaultsTmp = filepath.Join(os.TempDir(), "gc-cli-vaults-goreplay")
	for _, d := range []string{appTmp, vaultsTmp} {
		if err := os.RemoveAll(d); err != nil {
			t.Fatal(err)
		}
		if err := os.MkdirAll(d, 0o755); err != nil {
			t.Fatal(err)
		}
	}
	t.Cleanup(func() {
		_ = os.RemoveAll(appTmp)
		_ = os.RemoveAll(vaultsTmp)
	})

	t.Setenv("GITCURATOR_HOME", appTmp)
	t.Setenv("GITCURATOR_USER_CONFIG", filepath.Join(appTmp, "user-config.json"))
	t.Setenv("COLUMNS", "")

	for name, exists := range g.Env.Dirs {
		if exists {
			if err := os.MkdirAll(filepath.Join(vaultsTmp, name), 0o755); err != nil {
				t.Fatalf("mkdir vault dir: %v", err)
			}
		}
	}
	if err := os.MkdirAll(filepath.Join(appTmp, "taxonomy"), 0o755); err != nil {
		t.Fatalf("mkdir taxonomy: %v", err)
	}
	if err := os.WriteFile(filepath.Join(appTmp, "taxonomy", "taxonomy.json"),
		[]byte(`{"categories": []}`+"\n"), 0o644); err != nil {
		t.Fatalf("write taxonomy: %v", err)
	}

	cfg := decodeConfig(t, g.Env.Config, appTmp, vaultsTmp)
	if err := storage.WriteConfigFile(filepath.Join(appTmp, "config.json"), cfg); err != nil {
		t.Fatalf("write config.json: %v", err)
	}
	bad := decodeConfig(t, g.Env.BadConfig, appTmp, vaultsTmp)
	if err := storage.WriteConfigFile(filepath.Join(appTmp, "bad-config.json"), bad); err != nil {
		t.Fatalf("write bad-config.json: %v", err)
	}

	dbPath := filepath.Join(appTmp, "cache.db")
	cache, err := store.NewCacheDB(dbPath)
	if err != nil {
		t.Fatalf("open cache.db: %v", err)
	}
	for _, p := range g.Env.DB.Processed {
		_ = cache.AddProcessed(p.RepoID, p.URL, p.Owner, p.Repo, p.NotePath, p.Category)
	}
	for _, f := range g.Env.DB.Failed {
		cache.AddFailed(f.URL, f.Error)
	}
	// The quarantine rows: the reference drove its own record_404 with
	// the frozen clock (decommissioned_at = 2026-10-17T12:00:00); the
	// store's own stamps ride the live clock, so the replay inserts the
	// pinned rows directly — fixture state for the reader under test.
	for _, q := range g.Env.DB.Quarantine {
		if _, err := cache.SQL().Exec(
			"INSERT OR REPLACE INTO decommissioned_repos"+
				" (url, reason, decommissioned_at, fail_count)"+
				" VALUES (?, ?, ?, ?)",
			q.URL, q.Reason, q.At, q.Count); err != nil {
			t.Fatalf("insert quarantine row: %v", err)
		}
	}
	cache.Close()

	ns, err := notestate.New(dbPath)
	if err != nil {
		t.Fatalf("open note state: %v", err)
	}
	for _, u := range g.Env.DB.NoteState.Upserts {
		cat := u[4]
		if err := ns.Upsert(u[0], u[1], u[2], u[3], &cat, nil, false); err != nil {
			t.Fatalf("note upsert: %v", err)
		}
	}
	for _, cr := range g.Env.DB.NoteState.Corrections {
		fromCat, toCat := cr[2], cr[3]
		if err := ns.LogCorrection(cr[0], cr[1], &fromCat, &toCat, cr[4], cr[5], cr[6]); err != nil {
			t.Fatalf("log correction: %v", err)
		}
	}
	for _, d := range g.Env.DB.NoteState.Dismissed {
		if err := ns.Dismiss(d[0], d[1], ""); err != nil {
			t.Fatalf("note dismiss: %v", err)
		}
	}
	ns.Close()

	ws, err := websitepipeline.NewWebsiteStateDB(dbPath)
	if err != nil {
		t.Fatalf("open website state: %v", err)
	}
	for _, p := range g.Env.DB.Websites.Processed {
		if err := ws.MarkProcessed(p[0], p[1], p[2], p[3], p[4]); err != nil {
			t.Fatalf("website mark_processed: %v", err)
		}
	}
	for _, r := range g.Env.DB.Websites.Retries {
		url, _ := r[0].(string)
		errMsg, _ := r[1].(string)
		count, _ := r[2].(float64)
		for i := 0; i < int(count); i++ {
			if err := ws.EnqueueRetry(url, errMsg); err != nil {
				t.Fatalf("website enqueue_retry: %v", err)
			}
		}
	}
	for _, d := range g.Env.DB.Websites.Dismissed {
		reason := "note deleted by owner"
		if len(d) > 1 && d[1] != "" {
			reason = d[1]
		}
		if err := ws.Dismiss(d[0], reason); err != nil {
			t.Fatalf("website dismiss: %v", err)
		}
	}
	ws.Close()

	// the SESSION-028 wirings' crafted files.
	if err := os.WriteFile(filepath.Join(appTmp, "session.session"),
		[]byte{}, 0o644); err != nil {
		t.Fatalf("write session file: %v", err)
	}
	battery := decodeConfig(t, g.Env.Battery.Config, appTmp, vaultsTmp)
	if err := storage.WriteConfigFile(
		filepath.Join(appTmp, "battery-config.json"), battery); err != nil {
		t.Fatalf("write battery config: %v", err)
	}
	detectOllama := decodeConfig(t, g.Env.Detect.Ollama.Config, appTmp, vaultsTmp)
	if err := storage.WriteConfigFile(
		filepath.Join(appTmp, "detect-ollama-config.json"), detectOllama); err != nil {
		t.Fatalf("write detect-ollama config: %v", err)
	}
	detectLlama := decodeConfig(t, g.Env.Detect.Llamacpp.Config, appTmp, vaultsTmp)
	if err := storage.WriteConfigFile(
		filepath.Join(appTmp, "detect-llamacpp-config.json"), detectLlama); err != nil {
		t.Fatalf("write detect-llamacpp config: %v", err)
	}
	wizard1 := decodeConfig(t, g.Env.Wizard.Llamacpp.Config, appTmp, vaultsTmp)
	if err := storage.WriteConfigFile(
		filepath.Join(appTmp, "wizard1-config.json"), wizard1); err != nil {
		t.Fatalf("write wizard1 config: %v", err)
	}
	wizard2 := decodeConfig(t, g.Env.Wizard.Ollama.Config, appTmp, vaultsTmp)
	if err := storage.WriteConfigFile(
		filepath.Join(appTmp, "wizard2-config.json"), wizard2); err != nil {
		t.Fatalf("write wizard2 config: %v", err)
	}

	// SESSION-030 — the drivers' doors: the driver config (proxy OFF —
	// the preflight's proxy leg must not touch the network), the
	// confirm vault (one indexed note so the wrong-vault guard never
	// trips), the engine config, and THE SETTLEMENT primed (the
	// machine already ran its first --auto — the classification
	// answers like every LATER run).
	driver := decodeConfig(t, g.AutoGuard.Config, appTmp, vaultsTmp)
	if err := storage.WriteConfigFile(
		filepath.Join(appTmp, "driver-config.json"), driver); err != nil {
		t.Fatalf("write driver config: %v", err)
	}
	confirm := decodeConfig(t, g.AutoConfirm.Config, appTmp, vaultsTmp)
	if err := storage.WriteConfigFile(
		filepath.Join(appTmp, "confirm-config.json"), confirm); err != nil {
		t.Fatalf("write confirm config: %v", err)
	}
	confirmVault := filepath.Join(vaultsTmp, "confirm-vault")
	if err := os.MkdirAll(confirmVault, 0o755); err != nil {
		t.Fatalf("mkdir confirm vault: %v", err)
	}
	if err := os.WriteFile(filepath.Join(confirmVault, "indexed.md"), []byte(
		"---\nsource: https://github.com/owner/one\ncategory: "+
			"libraries\n---\n\n# Indexed\n"), 0o644); err != nil {
		t.Fatalf("write confirm note: %v", err)
	}
	engine := decodeConfig(t, g.EngineDryrun.Config, appTmp, vaultsTmp)
	if err := storage.WriteConfigFile(
		filepath.Join(appTmp, "engine-config.json"), engine); err != nil {
		t.Fatalf("write engine config: %v", err)
	}
	return appTmp, vaultsTmp
}

// resetUserConfig drops the mirrored user config after a saving
// section — the generator's own discipline (every load stays clean).
func resetUserConfig(t *testing.T, appTmp string) {
	t.Helper()
	_ = os.Remove(filepath.Join(appTmp, "user-config.json"))
}

// OSError is the worker /health fetch's stand-in for Python's OSError
// (the class token renders through errClass's %T last segment — the
// type NAME is the token, so it must be spelled exactly).
type OSError struct{}

func (OSError) Error() string { return "connection refused" }

// assertBytesEq fails with a display-safe diff: the raw strings are
// dumped with Go %q quoting (every control byte — including the ANSI
// escapes — becomes a visible escape, immune to display mangling).
func assertBytesEq(t *testing.T, name, got, want string) {
	t.Helper()
	if got == want {
		return
	}
	t.Fatalf("%s mismatch\n--- got ---\n%q\n--- want ---\n%q", name, got, want)
}

