// TestGoldenCLIMutation proves the differential has teeth: one byte
// changed in the golden's status card section must fail the replay's
// comparison.
func TestGoldenCLIMutation(t *testing.T) {
	g := loadGoldenCLI(t)
	appTmp, vaultsTmp := buildEnv(t, g)
	mutated := strings.Replace(g.StatusCard.Output,
		"Processed repos        2", "Processed repos        3", 1)
	if mutated == g.StatusCard.Output {
		t.Fatalf("mutation did not bite (pattern missing)")
	}
	c, buf := replayCLI(t, g, "")
	rc := c.Run([]string{"--status", "--config", filepath.Join(appTmp, "config.json")})
	if rc != g.StatusCard.RC {
		t.Fatalf("rc = %d, want %d", rc, g.StatusCard.RC)
	}
	got := fold(buf.String(), appTmp, vaultsTmp)
	if got == mutated {
		t.Fatalf("the mutated golden passed — the differential has no teeth")
	}
	if got != g.StatusCard.Output {
		t.Fatalf("the real replay diverged from the unmutated golden")
	}
}

// TestGoldenCLIMutationWirings — the SESSION-028 sections' teeth: one
// byte flipped in the wizard's SAVED CONFIG (the wizard's own write),
// in the hand-delivery queue.json (the enqueue's write), and in the
// detect card each fail their replay comparison.
func TestGoldenCLIMutationWirings(t *testing.T) {
	g := loadGoldenCLI(t)
	appTmp, vaultsTmp := buildEnv(t, g)

	// 1. the wizard's saved config: the detected model's tag byte.
	mutatedSaved := strings.Replace(g.WizardLlamacpp.SavedConfig,
		`"llamacpp_model": "qwen2.5-coder:7b"`,
		`"llamacpp_model": "qwen2.5-coder:7x"`, 1)
	if mutatedSaved == g.WizardLlamacpp.SavedConfig {
		t.Fatalf("wizard mutation did not bite (pattern missing)")
	}
	c, _ := replayCLI(t, g, unfold(strings.Join(g.Env.Wizard.Llamacpp.Script, ""), appTmp, vaultsTmp))
	radar := map[string]any{}
	for kind, det := range g.Env.Wizard.Llamacpp.Radar {
		pairs := []any{}
		for _, k := range []string{"kind", "vault_path", "repo_name", "confidence", "method", "detail"} {
			if v, ok := det[k]; ok && v != nil {
				pairs = append(pairs, k, v)
			}
		}
		radar[kind] = reporadar.NewDetection(pairs...)
	}
	c.RadarAll = func(cfg any) map[string]any { return radar }
	p := g.Env.Wizard.Llamacpp.Probe
	c.ProbeLlama = func(baseURL, apiKey string, timeoutS float64) *llmclient.ProbeResult {
		return &llmclient.ProbeResult{Found: p.Found, BaseURL: p.BaseURL,
			Models: p.Models, Model: p.Model, Detail: p.Detail}
	}
	if rc := c.Run([]string{"--init", "--config", filepath.Join(appTmp, "wizard1-config.json")}); rc != 0 {
		t.Fatalf("wizard rc = %d, want 0", rc)
	}
	saved, err := os.ReadFile(filepath.Join(appTmp, "wizard1-config.json"))
	if err != nil {
		t.Fatal(err)
	}
	gotSaved := fold(string(saved), appTmp, vaultsTmp)
	if gotSaved == mutatedSaved {
		t.Fatalf("the mutated wizard config passed — no teeth")
	}
	if gotSaved != g.WizardLlamacpp.SavedConfig {
		t.Fatalf("the real wizard write diverged from the unmutated golden")
	}
	resetUserConfig(t, appTmp)

	// 2. the hand-delivery queue.json: one byte in a stamp.
	mutatedQueue := strings.Replace(g.HandDelivery.QueueJSON,
		`"queued": "2026-10-17 12:00"`, `"queued": "2026-10-17 12:01"`, 1)
	if mutatedQueue == g.HandDelivery.QueueJSON {
		t.Fatalf("queue mutation did not bite (pattern missing)")
	}
	prevClock, prevFind, prevWOpen := handdelivery.Clock, handdelivery.FindChromeFn, handdelivery.WebbrowserOpenFn
	defer func() {
		handdelivery.Clock = prevClock
		handdelivery.FindChromeFn = prevFind
		handdelivery.WebbrowserOpenFn = prevWOpen
	}()
	handdelivery.Clock = frozenClock
	handdelivery.FindChromeFn = func() string { return "" }
	handdelivery.WebbrowserOpenFn = func(u string) (bool, error) {
		return false, fmt.Errorf("no browser")
	}
	c2, _ := replayCLI(t, g, "")
	if rc := c2.Run([]string{"--hand-delivery", "--config",
		filepath.Join(appTmp, "config.json")}); rc != 0 {
		t.Fatalf("hand-delivery rc = %d, want 0", rc)
	}
	vault := filepath.Join(vaultsTmp, "webvault")
	queueRaw, err := os.ReadFile(filepath.Join(handdelivery.HandDeliveryDir(vault), "queue.json"))
	if err != nil {
		t.Fatal(err)
	}
	gotQueue := fold(string(queueRaw), appTmp, vaultsTmp)
	if gotQueue == mutatedQueue {
		t.Fatalf("the mutated queue.json passed — no teeth")
	}
	if gotQueue != g.HandDelivery.QueueJSON {
		t.Fatalf("the real enqueue write diverged from the unmutated golden")
	}

	// 3. the detect card: one byte in the SET line.
	mutatedCard := strings.Replace(g.DetectOllama.Output,
		"model 'qwen2.5-coder:7b'", "model 'qwen2.5-coder:7x'", 1)
	if mutatedCard == g.DetectOllama.Output {
		t.Fatalf("detect mutation did not bite (pattern missing)")
	}
	c3, buf3 := replayCLI(t, g, "2\n")
	pr := g.Env.Detect.Ollama.Probe
	c3.DetectOllama = func(base string, timeoutS float64) llmclient.DetectOllamaResult {
		return llmclient.DetectOllamaResult{Found: pr.Found, BaseURL: pr.BaseURL,
			Models: pr.Models, Detail: pr.Detail}
	}
	if rc := c3.Run([]string{"--detect-llm", "ollama", "--config",
		filepath.Join(appTmp, "detect-ollama-config.json")}); rc != 0 {
		t.Fatalf("detect rc = %d, want 0", rc)
	}
	gotCard := fold(buf3.String(), appTmp, vaultsTmp)
	if gotCard == mutatedCard {
		t.Fatalf("the mutated detect card passed — no teeth")
	}
	if gotCard != g.DetectOllama.Output {
		t.Fatalf("the real detect card diverged from the unmutated golden")
	}
}

// TestGoldenCLIMutationPreflights — the SESSION-029 sections' teeth:
// one byte flipped in the preflight composition's output, in the LLM
// preflight's SAVED CONFIG (apply_model_choice's own write), and in the
// dry-run report's body each fail their replay comparison.
func TestGoldenCLIMutationPreflights(t *testing.T) {
	g := loadGoldenCLI(t)
	appTmp, vaultsTmp := buildEnv(t, g)

	// 1. the preflight_checks composition: one byte in the GitHub line.
	mutatedChecks := strings.Replace(g.PreflightChecks.Output,
		"authenticated as octo-owner", "authenticated as oct-ownex", 1)
	if mutatedChecks == g.PreflightChecks.Output {
		t.Fatalf("checks mutation did not bite (pattern missing)")
	}
	c, buf := replayCLI(t, g, "")
	c.PreflightGithub = func(string) PreflightGHReply {
		return PreflightGHReply{Status: 200, Login: "octo-owner"}
	}
	c.NetDial = func(string, int, int) (int, string) { return 42, "" }
	c.OllamaModels = func(string, float64) ([]string, error) {
		return g.Env.OllamaModels, nil
	}
	cfg := decodeConfig(t, g.PreflightChecks.Config, appTmp, vaultsTmp)
	if !c.PreflightChecks(cfg, true) {
		t.Fatal("checks rc = false, want true")
	}
	gotChecks := fold(buf.String(), appTmp, vaultsTmp)
	if gotChecks == mutatedChecks {
		t.Fatalf("the mutated checks card passed — no teeth")
	}
	if gotChecks != g.PreflightChecks.Output {
		t.Fatalf("the real checks card diverged from the unmutated golden")
	}

	// 2. the LLM preflight's saved config: the switched model's byte.
	var menuCase *goldenPreflightLLM
	for i := range g.PreflightLLM {
		if g.PreflightLLM[i].SavedConfig != "" &&
			g.PreflightLLM[i].Name == "ollama-menu-pick" {
			menuCase = &g.PreflightLLM[i]
		}
	}
	if menuCase == nil {
		t.Fatal("the menu-pick case is missing from the golden")
	}
	mutatedSaved := strings.Replace(menuCase.SavedConfig,
		`"model": "llama3"`, `"model": "llamaX"`, 1)
	if mutatedSaved == menuCase.SavedConfig {
		t.Fatalf("llm mutation did not bite (pattern missing)")
	}
	c2, _ := replayCLI(t, g, strings.Join(menuCase.Script, ""))
	c2.IsATTYIn = func() bool { return menuCase.TTY }
	c2.OllamaModels = func(string, float64) ([]string, error) {
		return menuCase.Answer.Models, nil
	}
	cfg2 := decodeConfig(t, menuCase.Config, appTmp, vaultsTmp)
	path2 := filepath.Join(appTmp, "llm-menu-config.json")
	if err := storage.WriteConfigFile(path2, cfg2); err != nil {
		t.Fatalf("write llm config: %v", err)
	}
	if !c2.preflightLLM(cfg2, path2) {
		t.Fatal("llm rc = false, want true")
	}
	raw2, err := os.ReadFile(path2)
	if err != nil {
		t.Fatal(err)
	}
	gotSaved := fold(string(raw2), appTmp, vaultsTmp)
	if gotSaved == mutatedSaved {
		t.Fatalf("the mutated llm config passed — no teeth")
	}
	if gotSaved != menuCase.SavedConfig {
		t.Fatalf("the real llm write diverged from the unmutated golden")
	}
	resetUserConfig(t, appTmp)

	// 3. the dry-run report's body: one byte in the preview cell.
	mutatedBody := strings.Replace(g.DryrunReport.Body,
		"the withheld content", "the withheld contenX", 1)
	if mutatedBody == g.DryrunReport.Body {
		t.Fatalf("report mutation did not bite (pattern missing)")
	}
	oldNow := dryrun.NowFn
	dryrun.NowFn = frozenClock
	defer func() { dryrun.NowFn = oldNow }()
	dryrun.Clear()
	dryrun.Enable()
	for _, e := range g.DryrunReport.Entries {
		var content any
		if e.Content != "" {
			content = e.Content
		}
		dryrun.Record(e.Op, unfold(e.Path, appTmp, vaultsTmp), content, e.Note)
	}
	dryrun.Disable()
	c3, _ := replayCLI(t, g, "")
	path3 := c3.writeDryrunReport()
	raw3, err := os.ReadFile(path3)
	if err != nil {
		t.Fatal(err)
	}
	gotBody := fold(string(raw3), appTmp, vaultsTmp)
	if gotBody == mutatedBody {
		t.Fatalf("the mutated report passed — no teeth")
	}
	if gotBody != g.DryrunReport.Body {
		t.Fatalf("the real report diverged from the unmutated golden")
	}
}

